// Отбор задач со сроком и расчёт ступени эскалации.
//
// Почему дедупликация — в $getWorkflowStaticData, а не во внешней БД:
// у нас нет другого хранилища, доступного n8n без новых компонентов, а нужен
// всего один маленький словарь {taskId: {lastStage, lastSentAt, dueMs, title, consequence}}
//.
// Статичные данные живут в записи workflow в БД n8n и переживают рестарты.
// Ограничение: они сохраняются только у активного workflow (production-запуски);
// при ручном «Test workflow» словарь не пишется — это нормально для проверки.
const P = $('Параметры').first().json;
if (!P.chat_id || String(P.chat_id).includes('REPLACE')) {
  throw new Error('Параметры → chat_id не задан: замени REPLACE_CHAT_ID на свой chat_id');
}
const lookaheadMs = Number(P.lookahead_min) * 60000;
const stage1Ms = Number(P.stage1_min) * 60000;
const stage2Ms = Number(P.stage2_min) * 60000;
const repeatMs = Number(P.repeat_min) * 60000;
const TZ = 'Europe/Moscow';

const unwrap = (j) => Array.isArray(j) ? j : (Array.isArray(j.results) ? j.results : (Array.isArray(j.items) ? j.items : []));
const tasks = $input.all().flatMap((i) => unwrap(i.json));
const projects = {};
for (const p of $('Todoist: проекты').all().flatMap((i) => unwrap(i.json))) projects[String(p.id)] = p.name;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Срок → миллисекунды UTC. Только дата → 23:59 по Москве (как в адаптере Portal).
function dueMs(due) {
  if (!due) return null;
  // Todoist API v1 кладёт дату-время в due.date («2026-09-20T11:53:05Z»); поля due.datetime нет.
  // Отличаем по "T": со временем — момент, без времени — весь день (конец дня по Москве).
  const raw = String(due.datetime || due.date || '');
  if (!raw) return null;
  if (raw.includes('T')) {
    if (/[zZ]|[+-]\d\d:?\d\d$/.test(raw)) return DateTime.fromISO(raw).toMillis();
    return DateTime.fromISO(raw, { zone: due.timezone || TZ }).toMillis();
  }
  return DateTime.fromISO(raw, { zone: TZ }).set({ hour: 23, minute: 59 }).toMillis();
}

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString(); // ts событий для портала
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const seen = new Set();
const out = [];

for (const t of tasks) {
  const id = String(t.id);
  seen.add(id);
  if (t.is_completed || t.checked) continue;
  const due = dueMs(t.due);
  if (due === null || due > nowMs + lookaheadMs) continue;

  const overdueMs = nowMs - due;
  const stage = overdueMs >= stage2Ms ? 2 : overdueMs >= stage1Ms ? 1 : 0;

  const prev = store.sent[id];
  const rescheduled = prev && prev.dueMs !== due; // срок перенесли — считаем задачу новой
  let send = false;
  if (!prev || rescheduled) send = true;
  else if (stage > prev.lastStage) send = true;
  else if (stage === 2 && nowMs - prev.lastSentAt >= repeatMs) send = true; // на 2-й ступени — каждый час
  if (!send) continue;

  const m = /последствие\s*[:—-]\s*(.+)/i.exec(t.description || '');
  const consequence = m ? m[1].trim() : null;
  const project = projects[String(t.project_id)] || '';
  const dueText = DateTime.fromMillis(due).setZone(TZ).toFormat('dd.MM HH:mm');
  const url = t.url || `https://app.todoist.com/app/task/${id}`;

  const header = stage === 0 ? '⏰ <b>Срок</b>'
    : stage === 1 ? '⏰⏰ <b>Час просрочки</b>'
    : '🔴🔴🔴 <b>ДВА ЧАСА ПРОСРОЧКИ</b>';
  const consLine = consequence
    ? (stage === 2 ? `<b>ПОСЛЕДСТВИЕ: ${esc(consequence).toUpperCase()}</b>` : `<b>Последствие:</b> ${esc(consequence)}`)
    : '⚠ <i>последствие не указано</i>';

  const text = [
    header,
    `<b>${esc(t.content)}</b>`,
    [project ? `📁 ${esc(project)}` : null, `🕒 ${dueText} МСК`].filter(Boolean).join(' · '),
    consLine,
    `<a href="${esc(url)}">открыть задачу</a>`,
  ].join('\n');

  // Событие в портал: первая ступень — «sent», остальные (и часовые повторы) — «escalated».
  const event = { task_id: id, stage, kind: stage === 0 ? 'sent' : 'escalated', ts: nowIso, task_title: t.content, consequence };
  out.push({ json: { notify: true, chat_id: String(P.chat_id), text, task_id: id, stage, event } });
  store.sent[id] = { lastStage: stage, lastSentAt: nowMs, dueMs: due, title: t.content, consequence };
}

// Задачи, которых больше нет в выдаче (закрыты/удалены): одно событие «closed» в портал и забыть —
// эскалация останавливается. Событие уходит ровно один раз: запись удаляется из словаря в этом же прогоне,
// а в Telegram такие элементы не идут (notify: false → IF «Есть сообщение?»).
for (const id of Object.keys(store.sent)) {
  if (seen.has(id)) continue;
  const prev = store.sent[id] || {};
  const stage = Number(prev.lastStage) || 0;
  out.push({ json: { notify: false, task_id: id, stage, event: {
    task_id: id, stage, kind: 'closed', ts: nowIso,
    task_title: prev.title || '(без названия)', consequence: prev.consequence ?? null,
  } } });
  delete store.sent[id];
}

return out; // 0 элементов → дальше ничего не выполняется

// Событие в портал — вспомогательное: его сбой не должен ломать напоминание, поэтому у HTTP-ноды
// continueOnFail, а здесь только фиксируем причину — в лог n8n и в данные выполнения.
const out = [];
for (const item of $input.all()) {
  const e = item.json.error;
  if (e === undefined) continue;
  const msg = typeof e === 'string' ? e : [e && e.message, e && e.description].filter(Boolean).join(' — ') || JSON.stringify(e);
  console.log('reminders/events не принят порталом: ' + msg);
  out.push({ json: { event_error: msg } });
}
return out;
